mapper.select:
SELECT SERVERIP serverIp, /* 服务器IP */ SERVERPORT serverPort, /* 服务器端口号 */ USERNAME serverName, /* 用户名 */ PASSWORD password, /* 服务器登录密码 */ SERVERTYPE serverType, /* 服务器登录类型 */ STATUS status, /* 状态 */ SYSTEMID systemID, /* 系统ID */ REMOTE_PATH remotePath, /* 远程路径 */ LOCAL_PATH localPath, /* 本地路径 */ RS rsStatus, /* 发送和接收 */ SERVERNAME execInfoId /*临时状态*/ FROM VAL_INTERF_SERVER_INFO WHERE 1 = 1 AND STATUS = 'Y'
AND RS = #{rsStatus}
AND SYSTEMID = #{systemID}
